package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/**
 * Markets content (content/data/markets.json, generated by tools/content/gen_markets.py).
 * docs/GDD.md §6 and docs/ECONOMY.md §5. All rates are per game day unless named otherwise.
 */
@Serializable
data class MarketContent(
    val config: MarketConfig,
    val macro: List<MacroPhaseDef>,
    val sectors: List<SectorDef>,
    val stocks: List<StockDef>,
    val funds: List<FundDef>,
    val bonds: List<BondDef>,
    val coins: List<CoinDef>,
    val commodities: List<CommodityDef>,
    val news: List<NewsTemplateDef>,
) {
    @kotlinx.serialization.Transient
    val instruments: List<InstrumentRef> = buildList {
        stocks.forEach { add(InstrumentRef(it.id, it.ticker, it.name, AssetClass.Stock)) }
        funds.forEach { add(InstrumentRef(it.id, it.ticker, it.name, AssetClass.Fund)) }
        bonds.forEach { add(InstrumentRef(it.id, it.ticker, it.name, AssetClass.Bond)) }
        coins.forEach { add(InstrumentRef(it.id, it.ticker, it.name, AssetClass.Crypto)) }
        commodities.forEach { add(InstrumentRef(it.id, it.ticker, it.name, AssetClass.Commodity)) }
    }

    @kotlinx.serialization.Transient
    val instrumentById: Map<String, InstrumentRef> = instruments.associateBy { it.id }

    @kotlinx.serialization.Transient
    val stockById: Map<String, StockDef> = stocks.associateBy { it.id }

    @kotlinx.serialization.Transient
    val coinById: Map<String, CoinDef> = coins.associateBy { it.id }

    @kotlinx.serialization.Transient
    val commodityById: Map<String, CommodityDef> = commodities.associateBy { it.id }

    @kotlinx.serialization.Transient
    val bondById: Map<String, BondDef> = bonds.associateBy { it.id }

    @kotlinx.serialization.Transient
    val fundById: Map<String, FundDef> = funds.associateBy { it.id }

    @kotlinx.serialization.Transient
    val sectorById: Map<String, SectorDef> = sectors.associateBy { it.id }

    companion object {
        val EMPTY = MarketContent(MarketConfig(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList())
    }
}

enum class AssetClass { Stock, Fund, Bond, Crypto, Commodity }

data class InstrumentRef(val id: String, val ticker: String, val name: String, val assetClass: AssetClass)

@Serializable
data class MarketConfig(
    val newsChancePerMinute: Double = 0.05,
    val hintReliability: Map<String, Double> = mapOf("Rumor" to 0.55, "Report" to 0.72, "Confirmed" to 0.9),
    val earningsEveryDays: Int = 3,
    val earningsSurpriseSd: Double = 0.035,
    val payoutEveryHours: Int = 6,
    val noiseReversionPerDay: Double = 2.0,
    /** Share of a stock's volatility carried by its fundamental random walk (the rest is mean-reverting noise). */
    val fundamentalVolShare: Double = 0.7,
    val slippageK: Double = 0.5,
    val slippageExponent: Double = 0.6,
    val slippageMax: Double = 0.5,
    val feeRate: Double = 0.001,
    val capitalGainsTax: Double = 0.10,
    val shortInitialMargin: Double = 1.5,
    val shortMaintenanceMargin: Double = 1.25,
    val borrowFeePerDay: Double = 0.002,
    val boardSeatStake: Double = 0.05,
    val boardSeatIncomeMultiplier: String = "1.05",
    val divisionStake: Double = 0.20,
    /** Opening a business whose sector you hold a division stake in costs this share of the normal price. */
    val divisionDiscount: String = "0.75",
    val fundDepthMultiplier: Double = 25.0,
    val bondDepthBillions: Double = 20_000.0,
    val commodityDepthBillions: Double = 500.0,
    val unlocks: Map<String, Int> = mapOf("stocks" to 2, "funds" to 2, "bonds" to 2, "crypto" to 3, "commodities" to 3, "shorts" to 5),
    /** Market depth (and shares outstanding) multiplier per story chapter, index 0 = chapter 1. */
    val depthScaleByChapter: List<Double> = listOf(1.0),
    val historyFineMinutes: Int = 15,
    val historyFinePoints: Int = 96,
    val historyCoarseMinutes: Int = 240,
    val historyCoarsePoints: Int = 42,
    val newsKept: Int = 40,
    /** Largest stake a player may hold in one listed company. */
    val maxStake: Double = 0.49,
)

@Serializable
data class MacroPhaseDef(
    val id: String,
    val name: String,
    val driftPerDay: Double,
    val ratePerDay: Double,
    val minDays: Double,
    val maxDays: Double,
    val next: Map<String, Double>,
)

@Serializable
data class SectorDef(val id: String, val name: String, val icon: String, val businesses: List<String>, val description: String)

@Serializable
data class StockDef(
    val id: String,
    val ticker: String,
    val name: String,
    val sector: String,
    val band: String,
    val trait: String,
    val driftPerDay: Double,
    val volPerDay: Double,
    val dividendPerDay: Double,
    val beta: Double,
    val baseCapBillions: Double,
    val startPrice: String,
)

@Serializable
data class FundDef(val id: String, val ticker: String, val name: String, val style: String, val feePerDay: Double, val description: String)

@Serializable
data class BondDef(
    val id: String,
    val ticker: String,
    val name: String,
    val kind: String,
    val duration: Double,
    val couponSpread: Double,
    /** Chance per payout (6 h) of a default while the economy is in recession. */
    val defaultChance: Double,
)

@Serializable
data class CoinDef(
    val id: String,
    val ticker: String,
    val name: String,
    val tier: Int,
    val driftPerDay: Double,
    val volPerDay: Double,
    val crashChancePerDay: Double,
    val crashDepthMin: Double,
    val crashDepthMax: Double,
    val stakingPerDay: Double,
    val baseCapBillions: Double,
    val startPrice: String,
    val risk: String,
)

@Serializable
data class CommodityDef(
    val id: String,
    val ticker: String,
    val name: String,
    val unit: String,
    val anchorPrice: String,
    val volPerDay: Double,
    val reversionPerDay: Double,
    val effects: List<CommodityEffectDef>,
)

@Serializable
data class CommodityEffectDef(val business: String, val mode: String, val elasticity: Double)

@Serializable
data class NewsTemplateDef(
    val id: String,
    val kind: String,
    val text: String,
    val min: Double,
    val max: Double,
    val weight: Int,
    val only: List<String> = emptyList(),
)
